"use client";

import { useReducedMotion } from "motion/react";
import {
  Fragment,
  type KeyboardEvent,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";

import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { ChevronRightIcon, PlusIcon } from "../parts/icons";
import { MinusIcon, PlayIcon } from "./icons";
import { nodeOf, NODES, pathTo, statsOf } from "./semantic-zoom/data";
import {
  useZoomCamera,
  frame,
  FULL_VIEW,
  zoomView,
} from "./semantic-zoom/use-zoom-camera";
import { ZoomMap } from "./semantic-zoom/zoom-map";
import { ZoomPanel } from "./semantic-zoom/zoom-panel";
import { ZoomTree } from "./semantic-zoom/zoom-tree";

const COUNTS = {
  teams: [...NODES.values()].filter((node) => node.level === "team").length,
  projects: [...NODES.values()].filter((node) => node.level === "project")
    .length,
  tasks: [...NODES.values()].filter((node) => node.level === "task").length,
};

const TOUR = ["root", "team-2", "team-2-p0", "team-2-p0-t1", "team-0", "root"];
const TOUR_STEP_MS = 1900;

const centre = (id: string) => {
  const node = nodeOf(id);
  return { x: node.x + node.w / 2, y: node.y + node.h / 2 };
};

/**
 * A zoomable map of Fernhill's work: teams hold projects, projects hold
 * tasks and people. A person flies in and out level by level, and each
 * level's detail fades in once it is large enough to read. A panel gives the
 * figures of the box under the cursor, and a hidden outline lists the
 * whole map for a screen reader.
 */
export function SemanticZoom({ className }: { className?: string }) {
  const titleId = useId();
  const reduceMotion = useReducedMotion() ?? false;
  const { view, flyTo, current: cameraNow } = useZoomCamera(reduceMotion);
  const [level, setLevel] = useState("root");
  const [cursor, setCursor] = useState("team-0");
  const [touring, setTouring] = useState(false);
  const tourTimer = useRef(0);

  useEffect(() => () => window.clearTimeout(tourTimer.current), []);

  const show = (id: string) => {
    const node = nodeOf(id);
    if (node.level === "task") {
      setLevel(node.parent!);
      setCursor(id);
      flyTo(frame(nodeOf(node.parent!)));
    } else if (node.level === "company") {
      setLevel("root");
      setCursor(node.children[0]!);
      flyTo(FULL_VIEW);
    } else {
      setLevel(id);
      setCursor(node.children[0]!);
      flyTo(frame(node));
    }
  };
  const stopTour = () => {
    window.clearTimeout(tourTimer.current);
    setTouring(false);
  };
  const startTour = () => {
    stopTour();
    setTouring(true);
    const run = (index: number) => {
      const id = TOUR[index];
      if (!id) {
        setTouring(false);
        return;
      }
      show(id);
      tourTimer.current = window.setTimeout(() => run(index + 1), TOUR_STEP_MS);
    };
    run(0);
  };
  const flyOut = () => {
    const node = nodeOf(level);
    if (!node.parent) return;
    show(node.parent);
    setCursor(level);
  };

  const move = (dx: number, dy: number) => {
    const from = centre(cursor);
    const options = nodeOf(level).children.filter((id) => id !== cursor);
    let best: string | null = null;
    let bestScore = Infinity;
    for (const id of options) {
      const to = centre(id);
      const along = (to.x - from.x) * dx + (to.y - from.y) * dy;
      if (along <= 0) continue;
      const across =
        Math.abs((to.x - from.x) * dy) + Math.abs((to.y - from.y) * dx);
      const score = along + across * 2;
      if (score < bestScore) {
        bestScore = score;
        best = id;
      }
    }
    if (best) setCursor(best);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const key = event.key;
    if (key === "ArrowLeft") move(-1, 0);
    else if (key === "ArrowRight") move(1, 0);
    else if (key === "ArrowUp") move(0, -1);
    else if (key === "ArrowDown") move(0, 1);
    else if (key === "Enter" || key === " ") {
      if (nodeOf(cursor).level !== "task") show(cursor);
    } else if (key === "Escape" || key === "Backspace") flyOut();
    else if (key === "+" || key === "=")
      flyTo(zoomView(cameraNow.current, 1.4));
    else if (key === "-" || key === "_")
      flyTo(zoomView(cameraNow.current, 1 / 1.4));
    else if (key === "0" || key === "Home") show("root");
    else return;
    event.preventDefault();
    stopTour();
  };

  const cursorNode = nodeOf(cursor);
  const cursorStats = statsOf(cursor);
  const factor = FULL_VIEW.w / view.w;
  const readout = `${cursorNode.name}: ${cursorStats.open} open ${cursorStats.open === 1 ? "task" : "tasks"}, ${Math.round(cursorStats.progress * 100)}% done.${cursorNode.level === "task" ? "" : " Enter zooms in."}`;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-start justify-between gap-x-6 gap-y-3 px-5 pt-5">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Fernhill at every scale
          </h2>
          <p className="text-sm text-muted-foreground">
            {COUNTS.teams} teams, {COUNTS.projects} projects and {COUNTS.tasks}{" "}
            tasks on one map.
          </p>
        </div>
        <Button
          variant="outline"
          size="sm"
          onClick={touring ? stopTour : startTour}
        >
          <PlayIcon aria-hidden="true" className="size-4" />
          {touring ? "Stop tour" : "Take the tour"}
        </Button>
      </header>

      <nav
        aria-label="Map level"
        className="flex flex-wrap items-center gap-0.5 px-4 pt-3"
      >
        {pathTo(level).map((node, index) => (
          <Fragment key={node.id}>
            {index > 0 ? (
              <ChevronRightIcon
                aria-hidden="true"
                className="size-3.5 text-muted-foreground"
              />
            ) : null}
            <Button
              variant="ghost"
              size="sm"
              aria-current={node.id === level ? "location" : undefined}
              onClick={() => {
                stopTour();
                show(node.id);
              }}
            >
              {node.name}
            </Button>
          </Fragment>
        ))}
      </nav>

      <div className="grid gap-5 px-5 py-3 @3xl:grid-cols-[1fr_15rem]">
        <div className="flex min-w-0 flex-col gap-2">
          <div
            role="application"
            aria-roledescription="zoomable map"
            aria-label="Work map. Arrows move between boxes, Enter zooms in, Escape zooms out, plus and minus zoom, Home fits the company."
            tabIndex={0}
            onKeyDown={onKeyDown}
            onPointerDown={stopTour}
            className="relative overflow-hidden rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <ZoomMap
              view={view}
              cursor={cursor}
              onPick={(id) => {
                stopTour();
                show(id);
              }}
            />
            <div className="absolute right-2 bottom-2 flex items-center gap-1 rounded-full border border-border bg-popover p-0.5 text-popover-foreground shadow-sm">
              <Button
                variant="ghost"
                size="icon"
                aria-label="Zoom out"
                onClick={() => flyTo(zoomView(cameraNow.current, 1 / 1.4))}
              >
                <MinusIcon className="size-4" />
              </Button>
              <span
                className="min-w-10 text-center text-xs font-medium tabular-nums"
                aria-live="polite"
              >
                {factor.toFixed(1)}x
              </span>
              <Button
                variant="ghost"
                size="icon"
                aria-label="Zoom in"
                onClick={() => flyTo(zoomView(cameraNow.current, 1.4))}
              >
                <PlusIcon aria-hidden="true" className="size-4" />
              </Button>
            </div>
          </div>
          <p role="status" className="text-sm text-muted-foreground">
            {readout}
          </p>
        </div>
        <ZoomPanel id={cursor} />
      </div>
      <ZoomTree />
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
export const ArrowDownIcon = packIcon("arrow-up", "rotate-180");
/** An arrow that points left, from the chosen icon pack. */
export const ArrowLeftIcon = packIcon("arrow-up", "-rotate-90");
/** An arrow that points up, from the chosen icon pack. */
export const ArrowUpIcon = packIcon("arrow-up");
/** A bell, from the chosen icon pack. */
export const BellIcon = packIcon("bell");
/** A calendar, from the chosen icon pack. */
export const CalendarIcon = packIcon("calendar");
/** A check mark, from the chosen icon pack. */
export const CheckIcon = packIcon("check");
/** A chevron that points down, from the chosen icon pack. */
export const ChevronDownIcon = packIcon("chevron-down");
/** A chevron that points right, from the chosen icon pack. */
export const ChevronRightIcon = packIcon("chevron-right");
/** A check mark in a circle, from the chosen icon pack. */
export const CircleCheckIcon = packIcon("circle-check");
/** A cross in a circle, from the chosen icon pack. */
export const CircleXIcon = packIcon("circle-x");
/** A download arrow, from the chosen icon pack. */
export const DownloadIcon = packIcon("download");
/** A globe, from the chosen icon pack. */
export const GlobeIcon = packIcon("globe");
/** An expand mark, from the chosen icon pack. */
export const MaximizeIcon = packIcon("expand");
/** A speech bubble, from the chosen icon pack. */
export const MessageIcon = packIcon("message");
/** A play mark, from the chosen icon pack. */
export const PlayerPlayFilledIcon = packIcon("play");
/** A plus, from the chosen icon pack. */
export const PlusIcon = packIcon("plus");
/** A refresh mark, from the chosen icon pack. */
export const RefreshIcon = packIcon("refresh");
/** Sparkles, from the chosen icon pack. */
export const SparklesIcon = packIcon("sparkles");
/** Two people, from the chosen icon pack. */
export const UsersIcon = packIcon("users");
/** A close mark, from the chosen icon pack. */
export const XIcon = packIcon("x");

/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
  </>,
);

/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
  <>
    <path d="M2.5 4.5h11M6 4.5V3a.5.5 0 0 1 .5-.5h3A.5.5 0 0 1 10 3v1.5" />
    <path d="M4 4.5l.6 8a1 1 0 0 0 1 .9h4.8a1 1 0 0 0 1-.9l.6-8M6.75 7v4M9.25 7v4" />
  </>,
);

import { ownIcon, packIcon } from "../parts/icons";

/** A minus sign, for zooming out. */
export const MinusIcon = ownIcon(<path d="M3.5 8h9" />);

/** A pause sign, for stopping a replay. */
export const PauseIcon = ownIcon(
  <path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />,
);

/** A clock, for the time of day. */
export const ClockIcon = packIcon("clock");

/** A grid of squares, for the grid layout. */
export const GridIcon = packIcon("layout-grid");

/** A list, for the list layout. */
export const ListIcon = packIcon("list");

/** Stacked sheets, for layers. */
export const LayersIcon = packIcon("layers");

/** A house, for the top of a map. */
export const HomeIcon = packIcon("home");

/** A play sign, for a guided tour. */
export const PlayIcon = packIcon("play");

import { seededRandom } from "../../lib/plot";

/** How deep a box sits: the company holds teams, a team holds projects, a project holds tasks. */
export type ZoomLevel = "company" | "team" | "project" | "task";

/** A task's state. */
export type TaskState = "done" | "open" | "blocked";

/** One box on the map, with its place in world units. */
export interface ZoomNode {
  id: string;
  name: string;
  level: ZoomLevel;
  x: number;
  y: number;
  w: number;
  h: number;
  /** Which chart hue the box and its children use, from 1 to 5. */
  hue: number;
  parent: string | null;
  children: string[];
  /** Set on tasks only. */
  state?: TaskState;
  /** Days after 11 November 2026 that a task is due. */
  due?: number;
  /** The people on a project or the owner of a task, as names. */
  people: string[];
}

/** The size of the whole map, in world units. */
export const WORLD = { w: 1000, h: 620 };

const TEAMS: { name: string; projects: string[] }[] = [
  {
    name: "Booking",
    projects: [
      "Waitlist offers",
      "Group sessions",
      "Online forms",
      "Reschedule by text",
    ],
  },
  {
    name: "Clinic success",
    projects: ["New clinic setup", "Training videos", "Health checks"],
  },
  {
    name: "Platform",
    projects: ["Faster calendar", "Room sync", "Audit log", "Data export"],
  },
  {
    name: "Growth",
    projects: ["Referral rewards", "Pricing page", "Trial emails"],
  },
  { name: "Payments", projects: ["Card on file", "Deposits", "Refund flow"] },
];

const PEOPLE = [
  "Ada Kerr",
  "Ben Ochoa",
  "Cara Doyle",
  "Dev Patel",
  "Esme Hart",
  "Finn Walsh",
  "Gita Rao",
  "Hugo Lind",
  "Iris Moon",
  "Jon Abara",
  "Kit Sato",
  "Lena Ford",
];
const TASK_VERBS = [
  "Draft",
  "Review",
  "Test",
  "Ship",
  "Measure",
  "Fix",
  "Write up",
  "Plan",
];
const TASK_OBJECTS = [
  "the copy",
  "edge cases",
  "the empty state",
  "reminders",
  "the API",
  "analytics",
  "access rules",
  "the rollout",
];

function build() {
  const random = seededRandom(5);
  const nodes = new Map<string, ZoomNode>();
  const add = (node: ZoomNode) => {
    nodes.set(node.id, node);
    if (node.parent) nodes.get(node.parent)?.children.push(node.id);
  };
  add({
    id: "root",
    name: "Fernhill",
    level: "company",
    x: 0,
    y: 0,
    w: WORLD.w,
    h: WORLD.h,
    hue: 1,
    parent: null,
    children: [],
    people: [],
  });
  // Three teams across the top row, two wider ones across the bottom.
  const slots = [
    [20, 20, 312, 280],
    [344, 20, 312, 280],
    [668, 20, 312, 280],
    [20, 320, 474, 280],
    [506, 320, 474, 280],
  ];
  TEAMS.forEach((team, teamIndex) => {
    const [tx, ty, tw, th] = slots[teamIndex]!;
    const teamId = `team-${teamIndex}`;
    add({
      id: teamId,
      name: team.name,
      level: "team",
      x: tx!,
      y: ty!,
      w: tw!,
      h: th!,
      hue: teamIndex + 1,
      parent: "root",
      children: [],
      people: [],
    });
    const columns = 2;
    const rows = Math.ceil(team.projects.length / columns);
    const pad = 12;
    const top = 44;
    const pw = (tw! - pad * (columns + 1)) / columns;
    const ph = (th! - top - pad * (rows + 1)) / rows;
    team.projects.forEach((project, projectIndex) => {
      const projectId = `${teamId}-p${projectIndex}`;
      const px = tx! + pad + (projectIndex % columns) * (pw + pad);
      const py =
        ty! + top + pad + Math.floor(projectIndex / columns) * (ph + pad);
      const people = Array.from(
        { length: 2 + Math.floor(random() * 3) },
        () => PEOPLE[Math.floor(random() * PEOPLE.length)]!,
      ).filter((name, index, list) => list.indexOf(name) === index);
      add({
        id: projectId,
        name: project,
        level: "project",
        x: px,
        y: py,
        w: pw,
        h: ph,
        hue: teamIndex + 1,
        parent: teamId,
        children: [],
        people,
      });
      const taskCount = 4 + Math.floor(random() * 3);
      const inset = pw * 0.06;
      const taskTop = py + ph * 0.3;
      const taskHeight = (ph * 0.56) / taskCount;
      for (let taskIndex = 0; taskIndex < taskCount; taskIndex++) {
        const roll = random();
        add({
          id: `${projectId}-t${taskIndex}`,
          name: `${TASK_VERBS[Math.floor(random() * TASK_VERBS.length)]} ${TASK_OBJECTS[Math.floor(random() * TASK_OBJECTS.length)]}`,
          level: "task",
          x: px + inset,
          y: taskTop + taskIndex * taskHeight,
          w: pw - inset * 2,
          h: taskHeight * 0.82,
          hue: teamIndex + 1,
          parent: projectId,
          children: [],
          state: roll < 0.45 ? "done" : roll < 0.88 ? "open" : "blocked",
          due: 1 + Math.floor(random() * 40),
          people: [people[taskIndex % people.length]!],
        });
      }
    });
  });
  for (const node of nodes.values()) {
    if (node.level === "team" || node.level === "company") {
      node.people = [
        ...new Set(node.children.flatMap((id) => nodes.get(id)?.people ?? [])),
      ];
    }
  }
  return nodes;
}

/** Every box on the map, by id. */
export const NODES = build();

/** Looks up a box. Every id the map hands out exists. */
export const nodeOf = (id: string) => NODES.get(id)!;

/** Every task under a box, the box itself included when it is a task. */
export function tasksUnder(id: string): ZoomNode[] {
  const node = nodeOf(id);
  return node.level === "task" ? [node] : node.children.flatMap(tasksUnder);
}

/** The figures the panel shows for a box. */
export function statsOf(id: string) {
  const tasks = tasksUnder(id);
  const done = tasks.filter((task) => task.state === "done").length;
  const open = tasks.filter((task) => task.state !== "done");
  const blocked = tasks.filter((task) => task.state === "blocked").length;
  const nextDue =
    open.length > 0 ? Math.min(...open.map((task) => task.due ?? 99)) : null;
  return {
    total: tasks.length,
    done,
    open: open.length,
    blocked,
    nextDue,
    progress: tasks.length ? done / tasks.length : 0,
  };
}

/** The chain of boxes from the company down to `id`. */
export function pathTo(id: string): ZoomNode[] {
  const path: ZoomNode[] = [];
  let node: ZoomNode | undefined = nodeOf(id);
  while (node) {
    path.unshift(node);
    node = node.parent ? nodeOf(node.parent) : undefined;
  }
  return path;
}

const DUE = new Intl.DateTimeFormat("en-GB", {
  day: "numeric",
  month: "short",
  timeZone: "UTC",
});

/** Writes a due day as a date such as "18 Nov". */
export const dueLabel = (days: number) =>
  DUE.format(new Date(Date.UTC(2026, 10, 11 + days)));

/** A person's initials, for an avatar. */
export const initials = (name: string) =>
  name
    .split(" ")
    .map((part) => part[0])
    .join("");

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import { easeInOut } from "../lib/spring";
import { WORLD, type ZoomNode } from "./data";

/** The part of the world in view, in world units. */
export interface ViewBox {
  x: number;
  y: number;
  w: number;
  h: number;
}

/** The view that fits the whole company. */
export const FULL_VIEW: ViewBox = { x: 0, y: 0, w: WORLD.w, h: WORLD.h };

const ASPECT = WORLD.w / WORLD.h;

/** The view that frames a box with a margin, keeping the map's shape. */
export function frame(
  node: Pick<ZoomNode, "x" | "y" | "w" | "h">,
  margin = 0.08,
): ViewBox {
  let w = node.w * (1 + margin * 2);
  let h = node.h * (1 + margin * 2);
  if (w / h > ASPECT) h = w / ASPECT;
  else w = h * ASPECT;
  return {
    x: node.x + node.w / 2 - w / 2,
    y: node.y + node.h / 2 - h / 2,
    w,
    h,
  };
}

/** The same view zoomed by `factor` around its centre. */
export function zoomView(view: ViewBox, factor: number): ViewBox {
  const w = Math.min(WORLD.w * 1.4, Math.max(WORLD.w / 40, view.w / factor));
  const h = w / ASPECT;
  return {
    x: view.x + view.w / 2 - w / 2,
    y: view.y + view.h / 2 - h / 2,
    w,
    h,
  };
}

/**
 * Flies the map's view between frames on an eased zoom. The eases run in
 * scale space, so the zoom feels even at every depth. With reduced motion
 * the view jumps.
 */
export function useZoomCamera(reduceMotion: boolean) {
  const [view, setView] = useState<ViewBox>(FULL_VIEW);
  const current = useRef(FULL_VIEW);
  const frameId = useRef(0);

  useEffect(() => () => cancelAnimationFrame(frameId.current), []);

  const flyTo = useCallback(
    (next: ViewBox) => {
      cancelAnimationFrame(frameId.current);
      if (reduceMotion) {
        current.current = next;
        setView(next);
        return;
      }
      const from = current.current;
      const start = performance.now();
      const span = Math.abs(Math.log(next.w / from.w));
      const duration = 450 + Math.min(500, span * 220);
      const tick = (now: number) => {
        const t = easeInOut(Math.min(1, (now - start) / duration));
        // Width moves by ratio, the centre by the same eased share, so zooms feel even.
        const w = from.w * (next.w / from.w) ** t;
        const cx =
          from.x +
          from.w / 2 +
          (next.x + next.w / 2 - (from.x + from.w / 2)) * t;
        const cy =
          from.y +
          from.h / 2 +
          (next.y + next.h / 2 - (from.y + from.h / 2)) * t;
        const h = w / ASPECT;
        const box = { x: cx - w / 2, y: cy - h / 2, w, h };
        current.current = box;
        setView(box);
        if (t < 1) frameId.current = requestAnimationFrame(tick);
      };
      frameId.current = requestAnimationFrame(tick);
    },
    [reduceMotion],
  );

  return { view, flyTo, current };
}

/** One value pulled toward a target by a spring, with the speed it carries. */
export interface SpringValue {
  value: number;
  velocity: number;
}

/**
 * Moves a spring one step toward `target`. The defaults are close to
 * critically damped, so a value arrives quickly and barely overshoots.
 * Returns true while the value is still moving.
 */
export function stepSpring(
  spring: SpringValue,
  target: number,
  seconds: number,
  stiffness = 170,
  damping = 26,
): boolean {
  // Small sub-steps keep a stiff spring stable on a slow frame.
  const steps = Math.max(1, Math.ceil(seconds / 0.008));
  const dt = seconds / steps;
  for (let index = 0; index < steps; index++) {
    const force =
      (target - spring.value) * stiffness - spring.velocity * damping;
    spring.velocity += force * dt;
    spring.value += spring.velocity * dt;
  }
  const moving =
    Math.abs(target - spring.value) > 0.0005 ||
    Math.abs(spring.velocity) > 0.0005;
  if (!moving) {
    spring.value = target;
    spring.velocity = 0;
  }
  return moving;
}

/** Makes a spring that rests at `value`. */
export const springAt = (value: number): SpringValue => ({
  value,
  velocity: 0,
});

/** Eases a value from 0 to 1 slowly at both ends. */
export const easeInOut = (t: number) =>
  t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2;

/** Keeps a value between two bounds. */
export const clamp = (value: number, low: number, high: number) =>
  Math.min(high, Math.max(low, value));

"use client";

import type { MouseEvent } from "react";

import { clamp } from "../lib/spring";
import {
  dueLabel,
  initials,
  nodeOf,
  NODES,
  statsOf,
  WORLD,
  type ZoomNode,
} from "./data";
import type { ViewBox } from "./use-zoom-camera";

/** Props for the drawn map of boxes. */
export interface ZoomMapProps {
  view: ViewBox;
  cursor: string;
  onPick: (id: string) => void;
}

const STATE_FILL = {
  done: "var(--chart-2)",
  open: "var(--chart-1)",
  blocked: "var(--chart-3)",
};

// A box shows a detail once it is drawn at least `from` world units wide at fit, fully by `to`.
const reveal = (width: number, from: number, to: number) =>
  clamp((width - from) / (to - from), 0, 1);

const tint = (hue: number, share: number) =>
  `color-mix(in oklch, var(--chart-${hue}) ${share}%, var(--card))`;

/**
 * The company as nested boxes in one SVG. The view box does the zooming, and
 * each level's detail fades in as its boxes grow large enough to read:
 * team figures first, then project titles, then tasks and people.
 */
export function ZoomMap({ view, cursor, onPick }: ZoomMapProps) {
  const scale = WORLD.w / view.w;
  const onClick = (event: MouseEvent<SVGSVGElement>) => {
    const node =
      event.target instanceof Element
        ? event.target.closest("[data-node]")
        : null;
    const id = node?.getAttribute("data-node");
    if (id) onPick(id);
  };
  const ring = (id: string) => (id === cursor ? "var(--foreground)" : "none");

  const projects = [...NODES.values()].filter(
    (node) => node.level === "project",
  );
  const teams = [...NODES.values()].filter((node) => node.level === "team");

  const drawTask = (task: ZoomNode, show: number) => (
    <g key={task.id} data-node={task.id} opacity={show}>
      <rect
        x={task.x}
        y={task.y}
        width={task.w}
        height={task.h}
        rx={task.h * 0.25}
        fill="var(--card)"
        stroke={ring(task.id)}
        strokeWidth={2}
        vectorEffect="non-scaling-stroke"
      />
      <circle
        cx={task.x + task.h * 0.5}
        cy={task.y + task.h / 2}
        r={task.h * 0.18}
        fill={STATE_FILL[task.state ?? "open"]}
      />
      <text
        x={task.x + task.h}
        y={task.y + task.h / 2}
        dominantBaseline="middle"
        fontSize={task.h * 0.42}
        className="fill-foreground"
      >
        {task.name}
      </text>
      <text
        x={task.x + task.w - task.h * 0.4}
        y={task.y + task.h / 2}
        dominantBaseline="middle"
        textAnchor="end"
        fontSize={task.h * 0.36}
        className="fill-muted-foreground"
      >
        {task.state === "done"
          ? "Done"
          : `${task.state === "blocked" ? "Blocked, due" : "Due"} ${dueLabel(task.due ?? 0)}`}
      </text>
    </g>
  );

  const drawProject = (project: ZoomNode) => {
    const width = project.w * scale;
    const title = reveal(width, 70, 140);
    const detail = reveal(width, 260, 420);
    const stats = statsOf(project.id);
    const avatar = project.h * 0.05;
    return (
      <g key={project.id} data-node={project.id}>
        <rect
          x={project.x}
          y={project.y}
          width={project.w}
          height={project.h}
          rx={6}
          fill={tint(project.hue, 10)}
          stroke={
            project.id === cursor ? "var(--foreground)" : tint(project.hue, 55)
          }
          strokeWidth={project.id === cursor ? 2 : 1}
          vectorEffect="non-scaling-stroke"
        />
        <rect
          x={project.x + project.w * 0.06}
          y={project.y + project.h * 0.2}
          width={project.w * 0.88}
          height={Math.max(1.5, project.h * 0.025)}
          rx={1}
          fill="var(--muted)"
          opacity={title}
        />
        <rect
          x={project.x + project.w * 0.06}
          y={project.y + project.h * 0.2}
          width={project.w * 0.88 * stats.progress}
          height={Math.max(1.5, project.h * 0.025)}
          rx={1}
          fill={`var(--chart-${project.hue})`}
          opacity={title}
        />
        <text
          x={project.x + project.w * 0.06}
          y={project.y + project.h * 0.12}
          dominantBaseline="middle"
          fontSize={Math.min(10, project.w * 0.055)}
          fontWeight={600}
          className="fill-foreground"
          opacity={title}
        >
          {project.name}
        </text>
        {detail > 0 ? (
          <g opacity={detail}>
            {project.children.map((id) => drawTask(nodeOf(id), detail))}
            {project.people.map((person, index) => (
              <g key={person}>
                <circle
                  cx={
                    project.x + project.w * 0.06 + avatar + index * avatar * 2.3
                  }
                  cy={project.y + project.h * 0.92}
                  r={avatar}
                  fill={tint(project.hue, 45)}
                />
                <text
                  x={
                    project.x + project.w * 0.06 + avatar + index * avatar * 2.3
                  }
                  y={project.y + project.h * 0.92}
                  textAnchor="middle"
                  dominantBaseline="central"
                  fontSize={avatar * 0.8}
                  className="fill-foreground"
                >
                  {initials(person)}
                </text>
              </g>
            ))}
          </g>
        ) : null}
      </g>
    );
  };

  return (
    <svg
      viewBox={`${view.x} ${view.y} ${view.w} ${view.h}`}
      className="block h-auto w-full select-none"
      aria-hidden="true"
      onClick={onClick}
    >
      <rect
        x={0}
        y={0}
        width={WORLD.w}
        height={WORLD.h}
        rx={14}
        fill="var(--muted)"
        opacity={0.5}
      />
      {teams.map((team) => {
        const stats = statsOf(team.id);
        const faded = reveal(team.w * scale, 2400, 4000);
        return (
          <g key={team.id} data-node={team.id}>
            <rect
              x={team.x}
              y={team.y}
              width={team.w}
              height={team.h}
              rx={10}
              fill={tint(team.hue, 16)}
              stroke={
                team.id === cursor ? "var(--foreground)" : tint(team.hue, 70)
              }
              strokeWidth={team.id === cursor ? 2.5 : 1.5}
              vectorEffect="non-scaling-stroke"
            />
            <text
              x={team.x + 14}
              y={team.y + 26}
              fontSize={19}
              fontWeight={600}
              className="fill-foreground"
              opacity={1 - faded}
            >
              {team.name}
            </text>
            <text
              x={team.x + team.w - 14}
              y={team.y + 26}
              fontSize={15}
              textAnchor="end"
              className="fill-muted-foreground"
              opacity={1 - faded}
            >
              {Math.round(stats.progress * 100)}% done
            </text>
          </g>
        );
      })}
      {projects.map(drawProject)}
    </svg>
  );
}

"use client";

import type { CSSProperties } from "react";

import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

import { formatWhole } from "../../lib/format";
import { dueLabel, initials, nodeOf, statsOf } from "./data";

const HUE_FILL = [
  "bg-chart-1",
  "bg-chart-2",
  "bg-chart-3",
  "bg-chart-4",
  "bg-chart-5",
];

const LEVEL_WORD = {
  company: "Company",
  team: "Team",
  project: "Project",
  task: "Task",
};

/**
 * The figures of the box under the cursor: open and blocked tasks, the next
 * due date, progress and the people on it. It rises in when the box changes.
 */
export function ZoomPanel({ id }: { id: string }) {
  const node = nodeOf(id);
  const stats = statsOf(id);
  const reduceMotion = useReducedMotion();
  const figures = [
    { label: "Open tasks", value: formatWhole(stats.open) },
    { label: "Blocked", value: formatWhole(stats.blocked) },
    {
      label: "Next due",
      value: stats.nextDue === null ? "Nothing due" : dueLabel(stats.nextDue),
    },
  ];
  return (
    <motion.div
      key={id}
      initial={reduceMotion ? false : { opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.25, ease: "easeOut" }}
      className="flex flex-col gap-4"
    >
      <div>
        <h3 className="text-base font-semibold">{node.name}</h3>
        <p className="text-xs text-muted-foreground">
          {LEVEL_WORD[node.level]}
        </p>
      </div>
      <dl className="grid grid-cols-3 gap-2 @3xl:grid-cols-1">
        {figures.map((figure) => (
          <div
            key={figure.label}
            className="flex flex-col gap-0.5 @3xl:flex-row @3xl:items-baseline @3xl:justify-between"
          >
            <dt className="text-xs text-muted-foreground">{figure.label}</dt>
            <dd className="text-sm font-semibold tabular-nums">
              {figure.value}
            </dd>
          </div>
        ))}
      </dl>
      <div className="flex flex-col gap-1.5">
        <div className="flex justify-between text-xs text-muted-foreground">
          <span>Progress</span>
          <span className="tabular-nums">
            {stats.done} of {stats.total} done
          </span>
        </div>
        <div
          role="progressbar"
          aria-label={`${node.name} progress`}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.round(stats.progress * 100)}
          className="h-1.5 rounded-full bg-muted"
        >
          <div
            className={cn(
              "h-full w-(--bar) rounded-full",
              HUE_FILL[node.hue - 1],
            )}
            // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
            style={{ "--bar": `${stats.progress * 100}%` } as CSSProperties}
          />
        </div>
      </div>
      {node.people.length > 0 ? (
        <div className="flex flex-col gap-1.5">
          <span className="text-xs text-muted-foreground">People</span>
          <ul className="flex flex-wrap gap-1">
            {node.people.slice(0, 10).map((person) => (
              <li
                key={person}
                title={person}
                className="flex size-7 items-center justify-center rounded-full bg-muted text-xs font-medium"
              >
                <span aria-hidden="true">{initials(person)}</span>
                <span className="sr-only">{person}</span>
              </li>
            ))}
          </ul>
        </div>
      ) : null}
    </motion.div>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

import { nodeOf, statsOf } from "./data";

/** A hidden outline of the whole map, so a screen reader can read every team, project and task in order. */
export function ZoomTree() {
  const root = nodeOf("root");
  return (
    <div className="sr-only">
      <h3>Outline of the map</h3>
      <ul>
        {root.children.map((teamId) => {
          const team = nodeOf(teamId);
          return (
            <li key={teamId}>
              {team.name}, {Math.round(statsOf(teamId).progress * 100)}% done
              <ul>
                {team.children.map((projectId) => {
                  const project = nodeOf(projectId);
                  return (
                    <li key={projectId}>
                      {project.name}
                      <ul>
                        {project.children.map((taskId) => {
                          const task = nodeOf(taskId);
                          return (
                            <li key={taskId}>
                              {task.name}, {task.state}
                            </li>
                          );
                        })}
                      </ul>
                    </li>
                  );
                })}
              </ul>
            </li>
          );
        })}
      </ul>
    </div>
  );
}
